import React, { useState } from "react";
import axios from "axios";
import { getFirestore, collection, addDoc } from "firebase/firestore";
import { app } from "../../../firebaseConfig"; // Firebase setup

const firestore = getFirestore(app);

const ImageUploader = () => {
  const [slider, setSlider] = useState([]);
  const [bigPhoto, setBigPhoto] = useState([]);
  const [allPhotos, setAllPhotos] = useState([]);
  const [uploadedData, setUploadedData] = useState({
    slider: [],
    bigPhoto: [],
    allPhoto: [],
  });

  const handleUpload = async () => {
    if (slider.length === 0 || bigPhoto.length === 0 || allPhotos.length === 0) {
      alert("Please select at least one Slider photo, one Big photo, and one All photo.");
      return;
    }

    const formData = new FormData();
    slider.forEach((img) => formData.append("slider", img));
    bigPhoto.forEach((img) => formData.append("bigPhoto", img));
    allPhotos.forEach((img) => formData.append("allPhotos", img));

    try {
      const { data } = await axios.post("http://localhost:5000/upload", formData);

      const structuredData = {
        slider: data.sliderUrls,
        bigPhoto: data.bigPhotoUrls,
        allPhoto: data.allPhotoUrls,
      };

      setUploadedData(structuredData);

      // Store in Firebase Firestore
      await addDoc(collection(firestore, "uploads-images"), {
        uploadedAt: new Date(),
        ...structuredData,
      });

      console.log("Images uploaded:", structuredData);
    } catch (error) {
      console.error("Upload failed", error);
    }
  };

  return (
    <div>
      <h3>Upload Slider Photos</h3>
      <input type="file" multiple onChange={(e) => setSlider(Array.from(e.target.files || []))} />

      <h3>Upload Big Photos</h3>
      <input type="file" multiple onChange={(e) => setBigPhoto(Array.from(e.target.files || []))} />

      <h3>Upload All Photos</h3>
      <input type="file" multiple onChange={(e) => setAllPhotos(Array.from(e.target.files || []))} />

      <button onClick={handleUpload}>Upload</button>

      {uploadedData.slider.length > 0 && (
        <div>
          <h3>Slider Photos</h3>
          {uploadedData.slider.map((url, index) => (
            <img key={index} src={url} alt={`Slider-${index}`} width="150px" />
          ))}
        </div>
      )}

      {uploadedData.bigPhoto.length > 0 && (
        <div>
          <h3>Big Photos</h3>
          {uploadedData.bigPhoto.map((url, index) => (
            <img key={index} src={url} alt={`BigPhoto-${index}`} width="150px" />
          ))}
        </div>
      )}

      {uploadedData.allPhoto.length > 0 && (
        <div>
          <h3>All Photos</h3>
          {uploadedData.allPhoto.map((url, index) => (
            <img key={index} src={url} alt={`AllPhoto-${index}`} width="150px" />
          ))}
        </div>
      )}
    </div>
  );
};

export default ImageUploader;
